#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int v, e;
    if (!(cin >> v >> e)) return 0;

    if (e == 0) {
        cout << 0 << '\n';
        return 0;
    }
    if (v <= 6) {
        cout << e << '\n';
        return 0;
    }

    vector<vector<int>> adj(v + 1);
    for (int i = 0; i < e; ++i) {
        int a, b;
        cin >> a >> b;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }

    array<unordered_set<int>, 8> neigh;
    for (int i = 1; i <= 7; ++i) {
        neigh[i] = unordered_set<int>(adj[i].begin(), adj[i].end());
    }

    bool f = false;
    int noOfVertices = INT_MAX;

    for (int j = 1; j <= 7 && !f; ++j) {
        for (int i = 1; i <= 7; ++i) {
            if (i == j) continue;
            int cnt = 0;
            if (neigh[j].size() < neigh[i].size()) {
                for (int u : neigh[j]) if (neigh[i].count(u)) ++cnt;
            } else {
                for (int u : neigh[i]) if (neigh[j].count(u)) ++cnt;
            }

            if (cnt == 0) {
                f = true;
                break;
            } else if (cnt < noOfVertices) {
                noOfVertices = cnt;
            }
        }
    }

    if (f) {
        cout << e << '\n';
    } else {
        cout << (e - noOfVertices) << '\n';
    }

    return 0;
}

